#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# This walkthrough's own helpers.
SITE="http://localhost:3000/fr"
PASSED=()
EMAIL=""
# The SasPay key goes to .env.local: it wins over .env (which may hold the live key) and is never committed.
ENV_FILE=".env.local"

# check "what": asks whether it worked; what didn't is listed at the end.
check() {
  if confirm "$1: did it work?"; then
    PASSED+=("$1")
  else
    SKIPPED+=("didn't work: $1")
  fi
}

# rows "SQL": prints the rows of one read-only query on the database in .env.
rows() {
  QUERY="$1" node -e '
    const { PrismaClient } = require("@prisma/client");
    const db = new PrismaClient();
    db.$queryRawUnsafe(process.env.QUERY)
      .then((r) => { if (r.length === 0) console.log("  (no rows)"); else console.table(r); })
      .catch((e) => console.error("  " + e.message))
      .finally(() => db.$disconnect());'
}

# sql "statement": runs one statement on the database in .env.
sql() {
  printf '%s' "$1" | npx prisma db execute --stdin --schema prisma/schema.prisma
}

# yours: the Consultations and their payments for every alias of the test e-mail (you+pay1@…, you+pay2@…).
yours() {
  local local_part="${EMAIL%@*}" domain="${EMAIL#*@}"
  rows "SELECT a.email, a.status AS compte, c.status,
               to_char(c.\"startsAt\" + interval '1 hour', 'Dy DD Mon HH24:MI') AS \"slot (Douala)\",
               to_char(c.\"heldUntil\" + interval '1 hour', 'HH24:MI:SS') AS \"held until\",
               p.\"networkName\" AS network, p.status AS payment, p.\"failureCode\" AS refused, p.charged,
               (c.\"meetingId\" IS NOT NULL) AS \"réunion\"
        FROM consultation c JOIN account a ON a.id = c.\"accountId\"
        LEFT JOIN consultation_payment p ON p.\"consultationId\" = c.id
        WHERE a.email = '$EMAIL' OR a.email LIKE '${local_part}+%@${domain}'
        ORDER BY c.\"createdAt\" DESC, p.\"createdAt\" DESC LIMIT 8"
}

# alias N: you+payN@domain, a fresh address (so a fresh Compte) for each booking.
alias_of() { printf '%s+pay%s@%s' "${EMAIL%@*}" "$1" "${EMAIL#*@}"; }

run_wizard() {

TOTAL_STAGES=12

banner "Walkthrough: paying a Consultation with SasPay (sandbox) (#15)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before we start"
say "You'll test, in the browser on your dev server, step 3 Paiement and the payment screens:"
note "  • a Mobile Money push that succeeds → « C'est réservé », the Réunion, the e-mail"
note "  • one that is refused → « Le paiement n'est pas passé », then paying another way"
note "  • one that never answers → « C'est plus long que prévu »"
note "  • card on SasPay's page, and SasPay bringing you back"
say ""
say "Everything goes through SasPay's SANDBOX: no real money moves. The app refuses a live key"
say "outside production, so the sk_live_ key in .env stays unused here."
warn "Your .env uses the Neon « test » database (real people in it) and sends real e-mails."
say ""
ask EMAIL "Your e-mail (each booking uses an alias of it: you+pay1@…, you+pay2@…)?"
EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
while [[ ! "$EMAIL" =~ ^[a-z0-9._%-]+@[a-z0-9.-]+\.[a-z]{2,}$ ]]; do
  warn "That doesn't look like an e-mail address (no « + » in it: the aliases add one)."
  ask EMAIL "Your e-mail?"
  EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
done
say ""
say "At each check, answer y or n: what didn't work is listed at the end."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "A SasPay sandbox key"
say "The sandbox is a separate SasPay account, with its own keys."
step "Open app.saspay.me, sign in, then in your account menu switch « Sandbox / Live » to Sandbox."
step "  (It signs you out and offers to create the sandbox account: e-mail + password, no KYC.)"
step "In the sandbox dashboard: Développeur → API keys → create a key (scope PAYIN or BOTH)."
step "Copy the key: it starts with sk_test_."
open_url "https://app.saspay.me"
say ""
SASPAY_API_KEY=""
ask_secret SASPAY_API_KEY "Paste the sandbox key (sk_test_…), hidden:"
while [[ "$SASPAY_API_KEY" != sk_test_* ]]; do
  warn "That isn't a sandbox key: it must start with sk_test_ (never paste sk_live_ here)."
  ask_secret SASPAY_API_KEY "Sandbox key (sk_test_…):"
done
write_env SASPAY_API_KEY "$SASPAY_API_KEY"
unset SASPAY_API_KEY
note "No webhook locally: SasPay can't reach localhost. The pages ask SasPay themselves instead."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The database, the price and the dev server"
say "This slice adds one migration (« consultation_payment »). It is already on « test »;"
say "running it again only checks."
if confirm "Run « npx prisma migrate deploy » and « prisma generate » now?"; then
  npx prisma migrate deploy && npx prisma generate >/dev/null && printf '  %s✓ database up to date%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("check the migrations: npx prisma migrate deploy && npx prisma generate")
fi
say ""
say "The price comes from the Tableau de bord (Consultations → Disponibilités). On « test » now:"
rows "SELECT price AS \"price (FCFA)\" FROM consultation_settings WHERE id = 'default'"
say "No screen sets it yet: without a price, step 3 only says payment opens soon."
if confirm "Set the price on « test » now (the default hours stay: Mon–Fri 09:00–17:00, 45 min)?"; then
  PRICE=""
  ask PRICE "Price in FCFA (digits only)?"
  while [[ ! "$PRICE" =~ ^[0-9]{3,7}$ ]]; do ask PRICE "Price in FCFA, digits only (e.g. no spaces)?"; done
  sql "INSERT INTO consultation_settings (id, price, \"durationMinutes\", \"bufferMinutes\", \"minNoticeHours\", \"horizonDays\", \"moveCutoffHours\", \"weeklyHours\", \"updatedAt\")
       VALUES ('default', $PRICE, 45, 15, 24, 30, 24,
               '[{\"day\":1,\"start\":\"09:00\",\"end\":\"17:00\"},{\"day\":2,\"start\":\"09:00\",\"end\":\"17:00\"},{\"day\":3,\"start\":\"09:00\",\"end\":\"17:00\"},{\"day\":4,\"start\":\"09:00\",\"end\":\"17:00\"},{\"day\":5,\"start\":\"09:00\",\"end\":\"17:00\"}]', now())
       ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, \"updatedAt\" = now()" >/dev/null \
    && printf '  %s✓ price set on « test »%s\n' "$GREEN" "$RESET"
  rows "SELECT price AS \"price (FCFA)\" FROM consultation_settings WHERE id = 'default'"
else
  SKIPPED+=("no price on « test »: step 3 shows « arrive très bientôt » instead of the networks")
fi
say ""
step "Restart « npm run dev » on the branch feat/consultation-booking, so it reads .env.local."
pause "Press Enter once the dev server is running again"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Step 3: SasPay's ways to pay"
open_url "$SITE/services/consultation"
step "Pick a slot, « Réserver ». Step 1 signed out with $(alias_of 1), country Cameroun,"
step "  WhatsApp number 6 77 12 34 50 (sandbox: a number ending in 0 succeeds). « Continuer »."
step "Step 2: anything, « Continuer vers le paiement »."
step "Step 3 shows « Payer depuis : Cameroun », the Cameroon networks SasPay's sandbox offers"
step "  (no fixed list in the app), the number from step 1, and « Payer … FCFA »."
step "On the right, the summary adds « Frais <network> » and « Total à payer »; choosing another"
step "  network changes them."
step "Mobile (Cmd+Shift+M): total and « Payer » sit in a bar at the bottom."
check "Step 3 lists SasPay's networks with their fee"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Paying, successfully"
step "Choose MTN Mobile Money (or the first network), keep the number ending in 0, « Payer »."
step "« Validez sur votre téléphone »: the request to your number, its three steps, « expire dans »."
step "Within a few seconds (the page asks SasPay itself): « C'est réservé, <prénom>. »"
step "  The check draws, Stanzy waves, a few confetti once. The navy ticket, « Aller à Mon espace »,"
step "  « Ajouter au calendrier » (downloads an .ics), and the receipt with SasPay's amounts."
say ""
say "In the database:"
yours
note "Expect: Consultation PAID, payment SUCCESS with its charged amount, réunion true, Compte LEAD."
check "A successful push delivers the Consultation"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The confirmation e-mail and Mon espace"
step "In $(alias_of 1)'s inbox: « Votre Consultation est confirmée : <date> (heure de Douala) »,"
step "  what was paid, « Ouvrir Mon espace ». (Also the Vérification e-mail from step 1.)"
step "Click the Vérification link first (it signs you in), then « Ouvrir Mon espace » from the"
step "  confirmation: it opens the Réunion's page (« Rejoindre » opens 15 minutes before)."
step "Tableau de bord, as the consultant: the Réunion « Consultation · <name> » is planned at the slot."
check "The confirmation e-mail, and the Réunion in Mon espace and the Tableau de bord"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "A refused payment"
step "Private window (signed out). Another slot, « Réserver », step 1 with $(alias_of 2),"
step "  number 6 77 12 34 51 (sandbox: ending in 1 fails). Step 2, then « Payer »."
step "« Le paiement n'est pas passé »: « Rien n'a été débité », « 0 FCFA débité », the slot still"
step "  held until its time, « Réessayer » and « Changer de moyen de paiement »."
step "E-mail to $(alias_of 2): « Votre paiement n'est pas passé », nothing charged, slot held until …"
yours
check "A refusal says nothing was charged and keeps the slot"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Paying another way after a refusal"
step "Same window: « Changer de moyen de paiement ». Step 3 again: change the number to"
step "  6 77 12 34 50, « Payer »: « C'est réservé »."
yours
note "Expect for $(alias_of 2): one payment FAILED, one SUCCESS, the Consultation PAID once."
check "After a refusal, another way pays and delivers once"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "A payment that never answers"
step "Private window again. Another slot, $(alias_of 3), number 6 77 12 34 59"
step "  (sandbox: ending in 9 stays pending forever). « Payer »."
step "« Validez sur votre téléphone » keeps turning. After 3 minutes: « C'est plus long que prévu »,"
step "  « Ne payez pas une deuxième fois », « Vérifier maintenant », « Écrire à Stanzy sur WhatsApp »."
step "« Vérifier maintenant »: it asks SasPay again and stays there."
yours
note "Expect: payment PENDING, the Consultation still HELD, its hold pushed back while paying."
check "A pending payment waits, never confirms, and can be checked again"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Card on SasPay's page"
step "Private window. Another slot, $(alias_of 4), country Cameroun, number ending in 0."
step "Step 3: « Payer depuis un autre pays » → Canada (any country, even without Mobile Money):"
step "  « Pas de Mobile Money pour ce pays », « Carte bancaire · débitée en USD au taux du jour »."
step "The summary: « Frais de paiement · calculés par SasPay », « Total avant frais »."
step "« Payer par carte »: a new tab opens for SasPay's card page. The sandbox may settle the card"
step "  at once and send no page: then the new tab closes and this one shows « On vérifie votre"
step "  paiement », then « C'est réservé »."
step "If SasPay's page opens: pay with a test card ending in 0; it sends that tab back to"
step "  …/reserver/paiement/<id> (« On vérifie… », then « C'est réservé ») and the first tab follows."
step "The receipt shows what SasPay charged in USD, with « Débité en USD par SasPay, au taux du jour »."
yours
check "Card on SasPay's page, and the page SasPay brings you back to"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Orange Money's code"
say "SasPay's sandbox doesn't ask for Orange Money CI's code (its « otp_required » is off there),"
say "so it can't be tried here; an automated test covers it. Just check nothing gets in the way:"
step "Private window. Another slot, $(alias_of 5), country Côte d'Ivoire, a number ending in 0."
step "Step 3 lists Côte d'Ivoire's networks (Orange Money, Wave, MTN, Moov, Djamo). Choose"
step "  Orange Money: no code block (sandbox), « Payer »: it goes through."
check "Côte d'Ivoire's networks, and Orange Money paying in the sandbox"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Done"
printf '  %s✓ %s check(s) passed%s\n' "$GREEN" "${#PASSED[@]}" "$RESET"
for item in "${PASSED[@]}"; do note "    ✓ $item"; done
say ""
say "The paid test Consultations stay in « test » with their Réunions (cancel them from the"
say "Tableau de bord if they bother you). Held ones free their slots by themselves."
say "The sandbox key stays in .env.local; remove the line to close payment locally again."
say ""
say "Send me what didn't work (listed below) and I'll look into it."
pause

finish
}

run_wizard "$@"; exit
